using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ChantingEffect", menuName = "Data/Battle/Effects/Sothis/Chanting Effect")]
public class ChantingEffect : Effect
{
	[Header("Achievement")]
	[SerializeField]
	private AchievementData royalChoirAchievementData;

	public string IfYouDealPurifyNotChantingLoseLocalized => Smart.Format(base.localizationManager.GetLocalizedString("IfYouDealPurifyNotChantingLose"), base.localizationManager.GetLocalizedLoseAllEffect(this).LowercaseFirst());

	public string IncreasesChantingPurifyChanting => base.localizationManager.GetLocalizedString("IncreasesChantingPurifyChanting");

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string arg = (amount + 1).ToString();
		if (amount == EffectsValues.NO_VALUE)
		{
			arg = base.localizationManager.GetLocalizedX();
		}
		return IncreasesChantingPurifyChanting + "\n" + Smart.Format(GetLocalizedDescription(), arg) + "\n" + IfYouDealPurifyNotChantingLoseLocalized;
	}

	public override void EffectIncreased(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (effectAmount >= royalChoirAchievementData.AchievementVariableAmount)
		{
			royalChoirAchievementData.Unlock();
		}
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		base.RemoveEffect(effectAmount, effectOwner);
		ReferenceSingleton<SothisOmensHandler>.Instance.ActivateSingingUrnOmen(effectAmount);
	}
}
